const filters=[['All stories','all'],['Adventure & wonder','adventure'],['Love & belonging','love'],['Power & conscience','ideas'],['Friendship & kindness','care']];
const categories={gatsby:'ideas',flies:'ideas','animal-farm':'ideas','swiss-family':'adventure',treasure:'adventure','west-side':'love',romeo:'love','charlottes-web':'care',huck:'ideas',oliver:'care','king-and-i':'ideas','sound-music':'adventure',alice:'adventure','mary-poppins':'care','charlie-wonka':'adventure',wonka:'adventure'};
const grid=document.querySelector('#bookGrid'), filterHost=document.querySelector('#filters');
let activeFilter='all', current=null, sceneIndex=0, stats={heart:0,nerve:0,insight:0}, notes=[], pending=null, soundOn=false, audioCtx=null;
const statNames={heart:'Empathy',nerve:'Courage',insight:'Insight'};
const traitStat={honesty:'insight',wonder:'heart',care:'heart',desire:'nerve',community:'heart',resolve:'nerve',justice:'insight',hope:'heart',bravery:'nerve',mercy:'heart',truth:'insight',vigilance:'insight',equity:'heart',freedom:'nerve',resourcefulness:'insight',curiosity:'insight',patience:'heart',boldness:'nerve',gratitude:'heart',adventure:'nerve',prudence:'insight',independence:'nerve',loyalty:'heart',caution:'insight',generosity:'heart',wisdom:'insight',bridge:'heart',insight:'insight',peace:'heart',restraint:'insight',healing:'heart',compassion:'heart',self-preservation:'nerve',understanding:'heart',trust:'heart',discernment:'insight',hope:'heart',belonging:'heart',attention:'insight',dignity:'heart',humility:'insight',openness:'heart',accountability:'insight',integrity:'nerve',strategy:'insight',resilience:'nerve',attunement:'heart',adaptability:'nerve',critical:'insight',creativity:'nerve',confidence:'nerve',playfulness:'heart',presence:'heart',inquiry:'insight',responsibility:'heart',self-control:'insight',fairness:'heart',devotion:'heart',collaboration:'heart',craft:'insight',transparency:'insight',joy:'heart',advocacy:'nerve',partnership:'heart',solidarity:'heart',courage:'nerve',self:'nerve'};
function renderFilters(){filterHost.innerHTML=filters.map(([label,key])=>`<button class="filter ${activeFilter===key?'active':''}" data-filter="${key}">${label}</button>`).join('');filterHost.querySelectorAll('button').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;renderFilters();renderBooks()})}
function renderBooks(){const shown=books.filter(b=>activeFilter==='all'||categories[b.id]===activeFilter);document.querySelector('#bookCount').textContent=`${shown.length} illustrated adventure${shown.length===1?'':'s'}`;grid.innerHTML=shown.map(b=>`<button class="book-card" data-book="${b.id}" aria-label="Play ${b.title}"><span class="book-icon">${b.icon}</span><span class="book-title">${b.title}</span><span class="book-author">${b.author}</span><span class="book-tag">${b.genre}</span><span class="card-arrow">↗</span></button>`).join('');grid.querySelectorAll('.book-card').forEach(card=>card.onclick=()=>startBook(card.dataset.book))}
function startBook(id){current=books.find(b=>b.id===id);if(!current)return;sceneIndex=0;stats={heart:0,nerve:0,insight:0};notes=[];document.querySelector('#libraryView').style.display='none';document.querySelector('#gameView').style.display='block';document.querySelector('#gameTitle').textContent=current.title;document.querySelector('#die').textContent='20';document.querySelector('#rollResult').textContent='Ready when you are';renderScene();window.scrollTo({top:0,behavior:'smooth'})}
function renderMeters(){const cap=Math.max(4,current.scenes.length+1);document.querySelector('#meters').innerHTML=Object.entries(statNames).map(([key,name])=>`<div class="meter"><div class="meter-head"><span>${name}</span><span>${stats[key]}</span></div><div class="meter-track"><div class="meter-fill" style="width:${Math.min(100,stats[key]/cap*100)}%"></div></div></div>`).join('')}
function renderScene(){const s=current.scenes[sceneIndex];document.querySelector('#actLabel').textContent=`Chapter ${sceneIndex+1} · ${current.scenes.length}`;document.querySelector('#artSymbol').textContent=current.icon;document.querySelector('#storyContent').innerHTML=`<div class="chapter-kicker">${current.genre} · a new page</div><h2>${s[0]}</h2><div class="story-copy">${s[1]}</div><div class="thought">${s[2]}</div><div class="choices">${s[3].map((c,i)=>`<button class="choice" data-choice="${i}"><span class="choice-num">${i===0?'A':'B'}</span><span class="choice-text">${c[0]}</span><span class="choice-hint">${c[1]}</span></button>`).join('')}</div>`;document.querySelectorAll('.choice').forEach(btn=>btn.onclick=()=>choose(Number(btn.dataset.choice)));renderMeters();const j=document.querySelector('#journal');j.innerHTML=`<strong>Your margin notes</strong>${notes.length?notes.slice(-2).map(n=>`<span>• ${n}</span>`).join('<br>'):'The first choice is still ahead.'}`;document.querySelector('#rollResult').textContent='Ready when you are'}
function choose(i){if(pending)return;const s=current.scenes[sceneIndex],c=s[3][i],stat=traitStat[c[2]]||'heart';stats[stat]++;notes.push(c[3]);pending={choice:c,stat};renderMeters();const die=document.querySelector('#die');die.classList.remove('rolling');void die.offsetWidth;die.classList.add('rolling');let ticks=0;const face=setInterval(()=>{die.textContent=1+Math.floor(Math.random()*20);ticks++;if(ticks>8)clearInterval(face)},75);const roll=1+Math.floor(Math.random()*20),bonus=Math.min(3,Math.floor(stats[stat]/2)),total=roll+bonus;pending.roll=roll;pending.total=total;setTimeout(()=>{die.classList.remove('rolling');die.textContent=roll;const degree=roll<=5?'A difficult turn':roll>=16?'A fortunate turn':'A complicated turn';document.querySelector('#rollResult').textContent=`d20 · ${roll}${bonus?` + ${bonus} ${statNames[stat]}`:''} = ${total}`;document.querySelector('#modalDie').textContent=roll>=16?'✦':roll<=5?'◌':'🎲';document.querySelector('#modalTitle').textContent=degree;document.querySelector('#modalText').textContent=roll>=16?`Your ${c[1].toLowerCase()} meets a lucky opening. ${c[3]} The story bends, but your choice is what gives the moment meaning.`:roll<=5?`The path answers with a complication—not a dead end. ${c[3]} You can still decide how to meet what follows.`:`The moment stays uncertain. ${c[3]} The next step is yours to shape.`;document.querySelector('#dieModal').classList.add('show');if(soundOn)playChime(roll)},700)}
function advance(){document.querySelector('#dieModal').classList.remove('show');if(!pending)return;if(sceneIndex<current.scenes.length-1){sceneIndex++;pending=null;renderScene()}else showEnding()}
function showEnding(){const best=Object.keys(stats).sort((a,b)=>stats[b]-stats[a])[0],qualities={heart:['a generous listener','Your attention became a shelter. You made room for other people’s truths, and that is a kind of courage.'],nerve:['a brave questioner','You chose not to let fear make every decision. Courage, here, meant staying answerable to what came next.'],insight:['a thoughtful witness','You looked past easy stories and asked what was really happening. Seeing clearly is one way to care.']};const [identity,reflection]=qualities[best];const storyEnd=current.scenes.at(-1),summary=storyEnd[2];document.querySelector('#actLabel').textContent='The end—for now';document.querySelector('#artSymbol').textContent=current.icon;document.querySelector('#storyContent').innerHTML=`<span class="ending-badge">Your ending · ${identity}</span><h2>The story stays with you.</h2><div class="story-copy">${reflection} In <em>${current.title}</em>, you chose <strong>${notes.length?notes[notes.length-1].toLowerCase():'your own way'}</strong>. The page closes, but the question remains: “${summary}”</div><div class="thought">${notes.length?notes.join(' '):'Every ending is also an invitation to begin again.'}</div><button class="restart-btn" id="replayBtn">↻ Play this story again</button>`;document.querySelector('#replayBtn').onclick=()=>startBook(current.id);document.querySelector('#rollResult').textContent=`Journey complete · ${notes.length} choices`;document.querySelector('#journal').innerHTML=`<strong>Your margin notes</strong>${notes.slice(-2).join('<br>')}`;renderMeters();let completed=[];try{completed=JSON.parse(localStorage.getItem('marginalia-completed')||'[]')}catch{}if(!completed.includes(current.id)){completed.push(current.id);try{localStorage.setItem('marginalia-completed',JSON.stringify(completed))}catch{}}pending=null}
function playChime(n){try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=300+n*16;gain.gain.setValueAtTime(.08,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.35);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.36)}catch{}}
document.querySelector('#continueBtn').onclick=advance;document.querySelector('#dieModal').onclick=e=>{if(e.target.id==='dieModal')advance()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#dieModal').classList.contains('show'))advance()});document.querySelector('#backBtn').onclick=()=>{document.querySelector('#gameView').style.display='none';document.querySelector('#libraryView').style.display='block';document.querySelector('#dieModal').classList.remove('show');pending=null;window.scrollTo({top:0,behavior:'smooth'})};document.querySelector('#libraryBtn').onclick=()=>document.querySelector('#backBtn').click();document.querySelector('#soundToggle').onclick=e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫ Sound on':'♫ Sound off';e.currentTarget.setAttribute('aria-pressed',String(soundOn))};renderFilters();renderBooks();
</script>
</body>

