            body=body[:-6] + ']]]]),' # no-op guard; actual count handled below
        # Remove exactly one bracket immediately before the final delimiter.
        if body.endswith(']]]]),'):
            body=body[:-6] + ']]]),'
        elif body.endswith(']]]]],'):
            body=body[:-6] + ']]]],'
        else:
            raise SystemExit(f'Unexpected scene ending on {number}: {body[-20:]!r}')
    else:
        if not body.endswith("']]]],"):
            raise SystemExit(f'Unexpected metadata ending on {number}: {body[-20:]!r}')
        body=body[:-5] + "']],"
    lines[number-1]=body+ending
