    line=lines[number-1]
    ending='\n' if line.endswith('\n') else ''
    body=line[:-1] if ending else line
    if number in scene_lines:
        if body.endswith('),'):
            body=body[:-3]+body[-2:] # remove one bracket before ),
        elif body.endswith(','):
            body=body[:-2]+body[-1:] # remove one bracket before comma
        else:
            raise SystemExit(f'Unexpected scene delimiter on {number}: {body[-20:]!r}')
    else:
        if not body.endswith(','):
            raise SystemExit(f'Unexpected metadata delimiter on {number}: {body[-20:]!r}')
        body=body[:-3]+body[-1:] # remove two brackets before comma
    lines[number-1]=body+ending
p.write_text(''.join(lines))
print('Corrected the previously over-adjusted delimiters.')
