const fs=require('fs');
const src=fs.readFileSync('index.html','utf8').match(/<script>([\s\S]*?)<\/script>/)[1];
const tail="document.querySelector('#continueBtn').onclick=advance;";
const cut=src.indexOf(tail);
if(cut<0) throw Error('cannot find startup block');
const code=src.slice(0,cut)+`return {books,casts,histories,categories,legacySteps,startBook,chooseLegacy,renderRoleSelect,renderScene,choose,advance,showEnding,getState:()=>({current,sceneIndex,generationIndex,legacy,stats,notes,outcomes,pending,currentRole})};`;
const elements=new Map();
function el(){return {innerHTML:'',textContent:'',style:{},dataset:{},classList:{add(){},remove(){},contains(){return false}},setAttribute(){},click(){},offsetWidth:0};}
const document={querySelector(sel){if(!elements.has(sel))elements.set(sel,el());return elements.get(sel)},querySelectorAll(){return []},addEventListener(){}};
const window={scrollTo(){}};
function interval(fn){for(let i=0;i<9;i++)fn();return 1}
const api=new Function('document','window','setTimeout','setInterval','clearInterval',code)(document,window,fn=>fn(),interval,()=>{});
const errors=[];
for(const book of api.books){
  const id=book.id, cast=api.casts[id], history=api.histories[id];
  if(!cast||cast.length!==3) errors.push(`${id}: cast invalid`);
  if(!history||history.length!==2||history[1].length!==3) errors.push(`${id}: history invalid`);
  if(!Array.isArray(book.scenes)||book.scenes.length<1) errors.push(`${id}: no scenes`);
  for(const [i,s] of (book.scenes||[]).entries()){
    if(!Array.isArray(s)||s.length!==4||!Array.isArray(s[3])||s[3].length!==2) errors.push(`${id}: scene ${i+1} malformed`);
    for(const [j,c] of (s[3]||[]).entries()) if(!Array.isArray(c)||c.length!==4) errors.push(`${id}: scene ${i+1} choice ${j+1} malformed`);
  }
  api.startBook(id);
  for(let i=0;i<3;i++) api.chooseLegacy(i%2);
  api.getState().currentRole={name:cast[0][0],role:cast[0][1],mood:cast[0][2]};
  api.renderScene();
  for(let i=0;i<book.scenes.length;i++){
    api.choose(i%2);
    api.advance();
  }
  const state=api.getState();
  if(state.outcomes.length!==book.scenes.length) errors.push(`${id}: ${state.outcomes.length}/${book.scenes.length} outcomes`);
  if(!document.querySelector('#storyContent').innerHTML.includes('The story stays with you.')) errors.push(`${id}: ending not rendered`);
}
console.log(`Validated ${api.books.length} stories; simulated complete playthroughs with ${api.books.reduce((n,b)=>n+b.scenes.length,0)} scene choices.`);
console.log(errors.length?errors.join('\n'):'All cast/history/scene structures and endings passed.');
if(errors.length) process.exitCode=1;
