const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const src=html.match(/<script>([\s\S]*?)<\/script>/)?.[1];
if(!src) throw Error('script not found');
const cut=src.indexOf("document.querySelector('#continueBtn').onclick=advance;");
if(cut<0) throw Error('cannot find startup block');
const code=src.slice(0,cut)+`return {books,casts,histories,categories,legacySteps,startBook,chooseLegacy,renderScene,choose,advance,setRole:r=>currentRole=r,getState:()=>({current,sceneIndex,generationIndex,legacy,stats,notes,outcomes,pending,currentRole})};`;
function makeDocument(){
 const els=new Map();
 const el=()=>({innerHTML:'',textContent:'',style:{},dataset:{},classList:{add(){},remove(){},contains(){return false}},setAttribute(){},click(){},offsetWidth:0});
 return {querySelector(s){if(!els.has(s))els.set(s,el());return els.get(s)},querySelectorAll(){return []},addEventListener(){}};
}
const errors=[]; let runs=0,sceneChoices=0;
for(const r of [0.01,0.5,0.99]){
 const doc=makeDocument(), win={scrollTo(){}};
 const math=Object.create(Math); math.random=()=>r;
 const api=new Function('document','window','setTimeout','setInterval','clearInterval','Math',code)(doc,win,fn=>fn(),()=>1,()=>{},math);
 for(const book of api.books){
  const id=book.id;
  if(!api.casts[id]||api.casts[id].length!==3) errors.push(`${id}: cast invalid`);
  if(!api.histories[id]||api.histories[id][1]?.length!==3) errors.push(`${id}: history invalid`);
  if(!api.categories[id]) errors.push(`${id}: category missing`);
  if(book.scenes?.length!==3) errors.push(`${id}: expected 3 scenes`);
  for(const [si,scene] of book.scenes.entries()){
   if(scene.length!==4||scene[3]?.length!==2||scene[3].some(c=>c.length!==4)) errors.push(`${id}: malformed scene ${si+1}`);
  }
  try{
   api.startBook(id);
   for(let i=0;i<3;i++) api.chooseLegacy((i+runs)%2);
   api.setRole({name:api.casts[id][0][0],role:api.casts[id][0][1],mood:api.casts[id][0][2]});
   api.renderScene();
   for(let i=0;i<book.scenes.length;i++){api.choose((i+runs)%2);api.advance();sceneChoices++;}
   const state=api.getState();
   const expected=r===0.01?'complication':r===0.99?'opening':'uncertain';
   if(state.outcomes.length!==book.scenes.length) errors.push(`${id}: incomplete outcome record`);
   if(state.outcomes.some(o=>o.kind!==expected)) errors.push(`${id}: expected ${expected} dice outcomes`);
   if(!doc.querySelector('#storyContent').innerHTML.includes('The story stays with you.')) errors.push(`${id}: ending not rendered`);
   if(!doc.querySelector('#storyContent').innerHTML.includes('Chapter 3')) errors.push(`${id}: ending path omitted final chapter`);
  }catch(e){errors.push(`${id}: ${e.stack}`)}
  runs++;
 }
}
console.log(`Checked ${runs} complete story runs (${sceneChoices} scene choices), spanning low, middle, and high d20 results.`);
console.log(errors.length?errors.join('\n'):'All cast/history/category/scene structures, dice outcome branches, and endings passed.');
if(errors.length)process.exitCode=1;
